{"command":"python3 << 'EOF'
with open('reports/pipeline_report.md', 'r') as f:
    content = f.read()

# Split by section headers
sections = ['Overview', 'Input data', 'Methods', 'Generated outputs', 'Main results', 'Limitations', 'Reproducibility']

# Get text after each header
header_pattern = r'^#\s+(\w+)$'
import re

for section in sections:
    # Find the section header
    pattern = rf'^#{section}\s*$'
    match = re.search(pattern, content, re.MULTILINE)
    if match:
        start = match.start()
        # Find the next header or end of file
        next_match = re.search(r'^#\s+\w+', content[start+1:], re.MULTILINE)
        if next_match:
            end = start + 1 + next_match.start()
        else:
            end = len(content)
        section_text = content[start:end]
        # Count non-whitespace characters
        chars = len(section_text)
        print(f"{section}: {chars} characters")
        if chars < 80:
            print(f"  WARNING: Less than 80 characters!")
            print(f"  Text: {repr(section_text)}")
    else:
        print(f"Section {section} not found!")
EOF"}

